// csrc/fused/sm_90/sg2_meta_tail.cu — host-launcher TU for the SuperGrok2 FULL
// CSA/HCA/PEER/GRU meta-net persistent megakernel (csrc/fused/sm_90/
// opt_stage_supergrok2.cuh). This is the INTEGRATION seam specified in
// INTEGRATION-NOTES.md §1: the §1b host wrapper body lives HERE (a .cu TU that
// nvcc compiles, so the `kernel<<<...>>>` launch + the device-templated
// `launch_sg2_meta_optimizer_tail<Dims,...>` are legal), while bindings.cpp
// (host-only .cpp) extern-declares + PYBIND11-registers the two entry points
// (it cannot #include the .cuh: host gcc cannot parse the launch syntax).
//
// TWO non-template host entry points, both with a plain torch::Tensor / scalar
// boundary (the same boundary every existing SG2 launcher uses):
//   sg::sg2_meta_optimizer_tail(...)  — marshals the packed buffers + meta
//       bundle + scalars into SG2Weights/SG2State/SG2Scalars/PersistentContext
//       and launches the persistent megakernel (the launch-elimination of
//       csa_hca_step_one's ~15-20 per-tensor launches).
//   sg::sg2_ws_stride(int64_t Nmax) -> int64_t  — exposes the AUTHORITATIVE
//       per-CTA workspace stride sg::fused::sm90::sg2_ws_stride<SG2Dims<>>(Nmax)
//       so the Python driver's host stride can never drift from the kernel's
//       carve (INTEGRATION-NOTES.md §2 "Strongly prefer binding ... directly").
//
// SETUP.PY: this TU is globbed into _ops by `csrc/fused/sm_90/*.cu` and owns NO
// PYBIND11_MODULE — so it is NOT dropped by setup.py's content-based filter
// (which removes only standalone-JIT cell drivers that define their own module)
// and does NOT collide on PyInit__ops. No glob edit needed.
//
// PRECISION / PARITY: fp32 throughout (matches csa_hca_step_one's fp32 compute
// and the parity-validated apply). Bit-faithful to the per-op math up to fp32
// reduction-order round-off in the hand-written GRU/PEER dots (the documented
// 1e-5 parity hotspots — see the .cuh header). NOT bit-identity.

#include <cuda_runtime.h>
#include <cstdint>

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>

#include "csrc/fused/sm_90/opt_stage_supergrok2.cuh"

namespace sg {

// Compile-time dims = supergrok2.py constructor defaults + OPTIMIZER_CONFIGS
// ["supergrok2"] (d_model=8, num_heads=2, gru_hidden=4, num_experts=144, ...).
// The race uses these defaults; a config with different shapes would template-
// specialize the launcher (compile-time dims). Mirrored in the Python driver +
// sg2_ws_stride below so the host packing/stride and the kernel carve agree.
using SG2DimsDefault = ::sg::fused::sm90::SG2Dims<>;

// ── sg2_ws_stride: the AUTHORITATIVE floats-per-CTA workspace stride. The
//    Python driver calls this (not a duplicated py formula) so the host
//    allocation and the kernel's sg2_carve_ws can never drift. ───────────────
int64_t sg2_ws_stride(int64_t Nmax) {
    return ::sg::fused::sm90::sg2_ws_stride<SG2DimsDefault>(Nmax);
}

// ── sg2_meta_optimizer_tail: the §1b host wrapper. Marshals the packed flat
//    buffers, the (fp32) meta weight bundle, the per-tensor + shared scalars,
//    and the persistent-context scratch into the POD structs, then launches the
//    ONE persistent kernel that runs CSA/HCA/GRU/PEER/apply for ALL tensors.
//    The argsort (perm/unsort) is PRE-COMPUTED by the driver (the one explicit
//    pre-kernel step — honesty rail #5). ──────────────────────────────────────
void sg2_meta_optimizer_tail(
    torch::Tensor params_packed,       // [total]   float32, all tensors back-to-back
    torch::Tensor grads_packed,        // [total]   float32
    torch::Tensor sharpness_packed,    // [total]   float32
    torch::Tensor exp_avg_packed,      // [total]   float32  (Adam m)
    torch::Tensor exp_avg_sq_packed,   // [total]   float32  (Adam v)
    torch::Tensor mu_packed,           // [total]   float32  (expert-output EMA)
    torch::Tensor slow_packed,         // [total]   float32  (grokfast slow EMA)
    torch::Tensor gru_state_packed,    // [total*gru_hidden] float32, row-major
    torch::Tensor perm_packed,         // [total]   int32  sorted-row -> original-row
    torch::Tensor unsort_packed,       // [total]   int32  original-row -> sorted-row
    torch::Tensor n_per_tensor,        // [P]       int32  element count of each tensor
    torch::Tensor row_off,             // [P]       int64  start element of each tensor
    torch::Tensor workspace,           // [n_ctas * ws_stride] float32 (kernel scratch)
    int64_t ws_stride,                 // floats per CTA (== sg2_ws_stride(Nmax))
    // ── meta weight bundle (fp32; upcast once by the driver) ──
    torch::Tensor input_proj_W, torch::Tensor input_proj_b,
    torch::Tensor csa_q_W, torch::Tensor csa_k_W, torch::Tensor csa_v_W, torch::Tensor csa_out_W,
    torch::Tensor csa_compress_w, torch::Tensor csa_idx_DQ, torch::Tensor csa_idx_K,
    torch::Tensor hca_q_W, torch::Tensor hca_k_W, torch::Tensor hca_v_W, torch::Tensor hca_out_W,
    torch::Tensor gru_Wz, torch::Tensor gru_bz, torch::Tensor gru_Wr, torch::Tensor gru_br,
    torch::Tensor gru_Wh, torch::Tensor gru_bh,
    torch::Tensor peer_query_Ws, torch::Tensor prod_keys_A, torch::Tensor prod_keys_B,
    torch::Tensor expert_W1, torch::Tensor expert_b1, torch::Tensor expert_W2, torch::Tensor expert_b2,
    // ── per-tensor scalars (length P) + shared scalars ──
    torch::Tensor alpha,        // [P] float  mu/slow mixing + slow-EMA decay (alpha_i)
    torch::Tensor gru_decay,    // [P] float  expert-EMA (mu) decay (== beta1_i)
    torch::Tensor lamb_eff,     // [P] float  grokfast amplification (lamb·ramp·gate)
    torch::Tensor beta1,        // [P] float  Adam beta1 (layer-scaled)
    torch::Tensor bc1,          // [P] float  1 - beta1_i^t
    torch::Tensor bc2,          // [P] float  1 - beta2^t
    double rescale,             // expert-output scale (shared)
    double beta2,               // shared
    double lr,                  // shared
    double wd,                  // shared  decoupled weight decay (wd_eff)
    double eps,                 // shared
    // ── persistent-context scratch (host-allocated, zero-init each launch) ──
    torch::Tensor g_next_task,  // int32   [1]  TaskQueue counter
    torch::Tensor g_arrived,    // int32   [1]  GridBarrier arrival count (reused as unsigned)
    torch::Tensor g_generation) // int32   [1]  GridBarrier generation (reused as unsigned)
{
    using namespace ::sg::fused::sm90;
    if (params_packed.numel() == 0) return;
    TORCH_CHECK(params_packed.scalar_type() == at::kFloat,
                "sg2_meta_optimizer_tail: fp32 packed buffers in this pass");
    TORCH_CHECK(perm_packed.scalar_type() == at::kInt &&
                unsort_packed.scalar_type() == at::kInt,
                "sg2_meta_optimizer_tail: perm/unsort must be int32");
    TORCH_CHECK(row_off.scalar_type() == at::kLong,
                "sg2_meta_optimizer_tail: row_off must be int64");
    TORCH_CHECK(n_per_tensor.scalar_type() == at::kInt,
                "sg2_meta_optimizer_tail: n_per_tensor must be int32");

    auto stream = at::cuda::getCurrentCUDAStream().stream();
    const int P = (int)n_per_tensor.numel();

    SG2Weights w {
        input_proj_W.data_ptr<float>(), input_proj_b.data_ptr<float>(),
        csa_q_W.data_ptr<float>(), csa_k_W.data_ptr<float>(), csa_v_W.data_ptr<float>(),
        csa_out_W.data_ptr<float>(), csa_compress_w.data_ptr<float>(),
        csa_idx_DQ.data_ptr<float>(), csa_idx_K.data_ptr<float>(),
        hca_q_W.data_ptr<float>(), hca_k_W.data_ptr<float>(), hca_v_W.data_ptr<float>(),
        hca_out_W.data_ptr<float>(),
        gru_Wz.data_ptr<float>(), gru_bz.data_ptr<float>(),
        gru_Wr.data_ptr<float>(), gru_br.data_ptr<float>(),
        gru_Wh.data_ptr<float>(), gru_bh.data_ptr<float>(),
        peer_query_Ws.data_ptr<float>(), prod_keys_A.data_ptr<float>(),
        prod_keys_B.data_ptr<float>(),
        expert_W1.data_ptr<float>(), expert_b1.data_ptr<float>(),
        expert_W2.data_ptr<float>(), expert_b2.data_ptr<float>() };

    SG2State st {
        exp_avg_packed.data_ptr<float>(), exp_avg_sq_packed.data_ptr<float>(),
        mu_packed.data_ptr<float>(), slow_packed.data_ptr<float>(),
        gru_state_packed.data_ptr<float>(),
        perm_packed.data_ptr<int>(), unsort_packed.data_ptr<int>(),
        workspace.data_ptr<float>(), (int64_t)ws_stride, P,
        n_per_tensor.data_ptr<int>(), row_off.data_ptr<int64_t>() };

    SG2Scalars sc {
        alpha.data_ptr<float>(), gru_decay.data_ptr<float>(), lamb_eff.data_ptr<float>(),
        beta1.data_ptr<float>(), bc1.data_ptr<float>(), bc2.data_ptr<float>(),
        (float)rescale, (float)beta2, (float)lr, (float)wd, (float)eps };

    ::sg::fused::PersistentContext ctx {};  // PersistentContext lives in sg::fused (parent of sm90)
    ctx.g_next_task  = g_next_task.data_ptr<int>();
    ctx.g_arrived    = reinterpret_cast<unsigned*>(g_arrived.data_ptr<int>());     // int32 buffer reused
    ctx.g_generation = reinterpret_cast<unsigned*>(g_generation.data_ptr<int>());
    ctx.n_tasks      = P;
    // n_ctas is set inside the launcher (== #SMs).

    // NOTE: bind to a temporary FIRST. The template arg list's commas would
    // otherwise be parsed by the preprocessor as extra C10_CUDA_CHECK macro
    // arguments ("passed 3 arguments, but takes just 1").
    cudaError_t launch_err =
        launch_sg2_meta_optimizer_tail<SG2DimsDefault, float, float>(
            ctx, w, st, sc,
            params_packed.data_ptr<float>(), grads_packed.data_ptr<float>(),
            sharpness_packed.data_ptr<float>(), stream);
    C10_CUDA_CHECK(launch_err);
}

}  // namespace sg

555	    //    apply_optimizer<GrokAdamW>. Guarded so every other opt's P3 is byte-identical
556	    //    (no extra barrier/work). loss_part (nCTA) + loss_out (1) are free scratch
557	    //    here: the reduced loss is already in *tok.loss_out (a separate pointer).
558	    if constexpr (Opt == OptId::GrokAdamW) {
559	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
560	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
561	        const int64_t total = kMambaTotalElems;
562	        const int64_t base = total / nCTA, rem = total % nCTA;
563	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
564	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
565	        float tsum = 0.0f;
566	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
567	            const float gv = grad[e0 + i];
568	            tsum += gv * gv;
569	        }
570	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
571	        float* red = sm.red;
572	        red[threadIdx.x] = tsum;
573	        __syncthreads();
574	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
575	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
576	            __syncthreads();
577	        }
578	        if (threadIdx.x == 0) sq_part[cta] = red[0];
579	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
580	        if (cta == 0 && threadIdx.x == 0) {
581	            double ss = 0.0;
582	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
583	            const float total_norm = sqrtf((float)ss);
584	            float coef = 1.0f;
585	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
586	                coef = st.grad_clip / (total_norm + 1e-6f);
587	            *coef_bc = coef;
588	        }
589	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
590	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
591	    }
592	
593	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. PORT of the
594	    //    decoder/vit TC kernels' P2.6 (fused_decoder_megakernel.cuh:514-568) onto the
595	    //    mamba constant tables.
596	    //    ⚠ LANDED-DORMANT / NOT PRODUCTION-ROUTED: mamba×prodigy is BLOCKED on a
597	    //    PRE-EXISTING A/A/A determinism failure SHARED by the decoder/vit prodigy P2.6
598	    //    (this port faithfully reproduces them; the failure is NOT in this code). The
599	    //    dispatch.cpp mamba carve-out (optimizer!="prodigy") + the Python has_l3_real
600	    //    gate keep this branch unreachable from the race until the shared prodigy P2.6
601	    //    (opt_stages_precompute.cuh) / GridBarrier (megakernel_common.cuh) is fixed by
602	    //    its owner. Kept here (if-constexpr'd, proven byte-identical for every non-Prodigy
603	    //    Opt) as the ready starting point for that fix. See dispatch.py's ⚠ escalation.
604	    //    The apply tail (apply_optimizer<Prodigy>) reads
605	    //    st.d_factor (the effective LR scale d), a GLOBAL reduction over EVERY element
606	    //    of EVERY parameter tensor. We compute it here, BYTE-FAITHFUL to the live eager
607	    //    multi-tensor path (prodigy_sm90.cuh:465-544, the order prodigy.py →
608	    //    _ops.prodigy_fused_step actually executes):
609	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state slot
610	    //                would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits _d_lr=d0,
611	    //                so seed it here, the grokfast-style step-1 fix)
612	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
613	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
614	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
615	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
616	    //    DETERMINISM (COMPONENT_CONTRACT): NO float atomic. Each CTA publishes its
617	    //    (r,s) into per-CTA slots (opt_reduce) → grid barrier → CTA0 owner-sums in
618	    //    ascending index order → writes d back to the persisted slot + a broadcast
619	    //    slot. The decay is on the persisted SCALARS (not the per-CTA partials): the
620	    //    work-steal queue reassigns tensors to CTAs across steps, so a per-CTA EMA is
621	    //    undefined — the live form is a scalar EMA (prodigy_sm90.cuh:488). Guarded so
622	    //    every other opt's P3 is byte-identical (no extra barrier/work).
623	    // DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
624	    // P2.5 + the decoder/vit twins' P2.6), NOT the work-steal task-queue drain.
625	    // WHY THIS SHAPE (the A/A/A determinism leg): the work-steal phaseA drained the
626	    // global TaskQueue (atomicAdd(g_next_task)) in timing-dependent claim order, so
627	    // each CTA's (r,s) slot could be a different tensor subset run-to-run; with non-
628	    // associative fp32 add the partials regroup differently and the owner's d can
629	    // differ at ULP level from step>=2 — a COMPONENT_CONTRACT deterministic-reduction
630	    // violation (not reproducible BY CONSTRUCTION). A FIXED contiguous element range
631	    // per CTA over the FLAT [0,kMambaTotalElems) arrays (params/param_init/grad are
632	    // parallel flat blobs → flat Σ == cross-tensor Σ) with a plain sync() is the
633	    // IDENTICAL shape as the A/A/A-CLEAN GrokAdamW P2.5 — deterministic by
634	    // construction. Per-element math still CALLS canonical prodigy_partials_step
635	    // (prodigy.h, single-source). g_next_task is UNTOUCHED (B2 reset it), so P3's
636	    // drain is unchanged — no sync_reset in P2.6. (mamba×prodigy is dispatch-gated to
637	    // eager today on a SEPARATE mamba scan/forward determinism issue; this keeps the
638	    // landed-dormant P2.6 correct + deterministic.)
639	    if constexpr (Opt == OptId::Prodigy) {
640	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
641	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
642	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
643	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
644	        const int64_t total_p = kMambaTotalElems;

639	    if constexpr (Opt == OptId::Prodigy) {
640	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
641	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
642	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
643	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
644	        const int64_t total_p = kMambaTotalElems;
645	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
646	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
647	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
648	        float r_acc = 0.0f, s_acc = 0.0f;
649	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
650	            algo::prodigy_partials_step(params, st.param_init, grad,
651	                                        d_prev, pe0 + i, r_acc, s_acc);
652	        }
653	        float r_block, s_block;
654	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
655	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
656	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
657	        if (cta == 0 && threadIdx.x == 0) {
658	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
659	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
660	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
661	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
662	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
663	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
664	            st.prodigy_persist[1] = s_ema;
665	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
666	            d_bc[0]               = d_new;          // broadcast to all CTAs
667	        }
668	        bar.sync();   // B2.6b: d visible to every CTA before the apply
669	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
670	    }
671	
672	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal 28). ──
673	    st.lr = lr;
674	    {
675	        __shared__ int task_slot;
676	        TaskQueue q = ctx.queue();
677	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
678	             t = q.next_block(&task_slot)) {
679	            const int n = kMambaSizes[t];
680	            const int64_t off = (int64_t)kMambaOffsets[t];
681	            FusedOptState ts = mamba_rebase_state<Opt>(st, off);
682	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only) — PORT of the decoder
683	            //     P3 (fused_decoder_megakernel.cuh:587-591): β1_i = β1·(1-γ)^t, where
684	            //     t == the tensor's flat named_parameters() layer index (the work-steal
685	            //     task id maps 1:1 to kMambaOffsets order == the eager enumeration
686	            //     order, so t IS the eager layer index). bc1 must be rebased TOO
687	            //     (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager; bc2 stays global
688	            //     (β2 is not layer-wise). This is the mechanism that fails the STEP-1
689	            //     STATE gate when dropped (decoder observed m-rel 0.895).
690	            if constexpr (Opt == OptId::GrokAdamW) {
691	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
692	                ts.beta1 = b1;
693	                ts.bc1   = 1.0f - powf(b1, (float)step);
694	            }
695	            float* __restrict__ p = params + off;
696	            const float* __restrict__ gg = grad + off;
697	            for (int i = threadIdx.x; i < n; i += blockDim.x)
698	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
699	        }
700	    }
701	    SG_MBTC_PROF_ACC(3, _pt);          // close P3
702	}
